const sizeRange = t => t.sz ? [t.sz] : t.q.find(q => q.id === 'scope') ? t.q.find(q => q.id === 'scope').o.map(o => o[2]) : [t.path === 'newpage' ? 'L' : t.path === 'content' ? 'M' : 'S'];
