function schedule(Ts) { const st = {}, en = {}; const go = t => { if (en[t.id] != null) return en[t.id]; let s = 0; t.d.forEach(d => { const x = Ts.find(z => z.id === d); if (x) s = Math.max(s, go(x)); }); st[t.id] = s; en[t.id] = s + (t.days || 0.5); return en[t.id]; }; Ts.forEach(go); return { st, en, total: Math.max(0, ...Ts.map(t => en[t.id])) }; }
const agentsOf = Ts => [...new Set(Ts.flatMap(t => t.a.split(/ \+ /)).filter(x => !/людина|Тест-гейт|Gateway|дизайнер|інтерв|Менеджер/.test(x)))];
