  const col = s => ({ XS: '#B7BFEC', S: '#8A96E0', M: '#5B6BD0', L: '#3442A8' }[s] || '#8A96E0');
  let s = `<svg viewBox="0 0 ${W} ${H}">`; const step = span > 40 ? 7 : span > 14 ? 2 : 1;
  for (let d = 0; d <= span; d += step) s += `<line x1="${x(d)}" x2="${x(d)}" y1="16" y2="${H - 10}" stroke="#E3E7EF"/><text x="${x(d)}" y="11" font-size="10.5" text-anchor="middle" fill="#8A93A8">${d}</text>`;
  Ts.forEach((t, i) => { const y = Tp + i * rh; s += `<text x="${L - 8}" y="${y + 14}" font-size="11" text-anchor="end" fill="${t.ph3 ? '#7B3FA0' : '#182033'}">${esc(t.t.length > 46 ? t.t.slice(0, 45) + '…' : t.t)}</text><rect x="${x(sch.st[t.id])}" y="${y + 4}" width="${Math.max(5, x(sch.en[t.id]) - x(sch.st[t.id]))}" height="14" rx="4" fill="${t.id.startsWith('X') ? '#F4EAD1' : t.ph3 ? '#F1EAF7' : col(t.s)}" stroke="${isHuman(t) ? '#B86E00' : 'none'}" stroke-width="2"><title>${esc(t.t)} · ${esc(t.a)}</title></rect>`; });
  return `<div class="bf-tl">${s}</svg></div><div class="bf-legend"><span><i style="background:#F4EAD1"></i>перевірки контексту</span><span><i style="background:#B7BFEC"></i>XS</span><span><i style="background:#8A96E0"></i>S</span><span><i style="background:#5B6BD0"></i>M</span><span><i style="border:2px solid #B86E00"></i>людина</span><span><i style="background:#F1EAF7"></i>фаза 3</span><span>дні від старту</span></div>`;
