  ['Перевірки контексту', 'Ресерч', 'Структура і дизайн', 'Контент', 'SEO', 'Запуск'].forEach((t, i) => { s += box(490, 6 + i * 42, 180, 34, i === 0 ? 'S' : 'M', t, ''); });
  [['Конкуренти', 'S'], ['Семантика', 'S'], ['Формат SERP', 'XS'], ['Hero + CTA', 'XS'], ['FAQ + schema', 'S'], ['Title, meta', 'XS'], ['М’який запуск', 'S']].forEach(([t, z], i) => { s += box(700, 10 + i * 33, 170, 28, z, t, ''); });
  s += box(900, 60, 190, 60, 'XS', 'Одна задача', 'один агент, одні ворота');
  const ln = (a, b, c, d) => `<path d="M${a} ${b} C${(a + c) / 2} ${b} ${(a + c) / 2} ${d} ${c} ${d}" fill="none" stroke="#C3CAD8" stroke-width="1.5"/>`;
