  if (typeof slack === 'function') slack(`Бриф <b>${esc(t.n)}</b> виконано: ${Ts.length} задач, розмір ${sizeNow()}. ${t.out(A).filter(Boolean).map(esc).join('; ')}.`, [{ label: 'Відкрити бриф', action: 'nav-to', screen: 'brief' }]);
